def inventory(start,events):
 d=dict(start)
 for k,v in events:d[k]=max(0,d.get(k,0)+v)
 return d

def leaderboard(events,k):
 d={}
 for n,p in events:d[n]=d.get(n,0)+p
 return sorted(d.items(),key=lambda x:-x[1])[:max(0,k)]

def schedule(jobs,limit):
 out=[]; now=0
 for id,r,d in sorted(jobs,key=lambda j:j[1]):
  s=max(now,r); f=s+d
  if f<=limit:out.append((id,s,f)); now=f
 return out

def runs(values):
 out=[]
 for i,v in enumerate(values):
  if out and out[-1][0]==v:out[-1]=(v,out[-1][1],i+1)
  else:out.append((v,i,i+1))
 return out
